-- ====================================================================================================
-- ETIMETRACKLITE NATIVE MS SQL ATTENDANCE & BIOMETRIC SYNC SCRIPT
-- Department: Purva Venezia (18 Corrected Employees across 26-Jul-2026 to 25-Aug-2026)
-- Architecture:
--   1. Clean Sync of Raw Punches into dbo.DeviceLogs, dbo.DeviceLogs_7_2026, dbo.DeviceLogs_8_2026
--   2. Direct Native Update of Shift Attendance Records in dbo.AttendanceLogs
--   3. Pure standard T-SQL — no triggers, no extra tables.
-- ====================================================================================================

USE [etimetracklite1];
GO

SET NOCOUNT ON;
PRINT '======================================================================';
PRINT '  Starting Native eTimeTrackLite Sync for Purva Venezia';
PRINT '======================================================================';
PRINT '';

-- Clean up any earlier custom trigger or table
IF OBJECT_ID('dbo.trg_AttendanceLogs_PurvaVenezia_AutoSync', 'TR') IS NOT NULL
    DROP TRIGGER dbo.trg_AttendanceLogs_PurvaVenezia_AutoSync;
IF OBJECT_ID('dbo.ExcelAttendanceMaster_PurvaVenezia', 'U') IS NOT NULL
    DROP TABLE dbo.ExcelAttendanceMaster_PurvaVenezia;
GO

-- 1. Create Temporary Tables for Bulk Operations (Auto-dropped when script finishes)
IF OBJECT_ID('tempdb..#CleanPunches') IS NOT NULL DROP TABLE #CleanPunches;
IF OBJECT_ID('tempdb..#CleanAttendance') IS NOT NULL DROP TABLE #CleanAttendance;

CREATE TABLE #CleanPunches (
    UserId VARCHAR(50),
    LogDate DATETIME,
    Direction VARCHAR(20),
    PRIMARY KEY (UserId, LogDate)
);

CREATE TABLE #CleanAttendance (
    EmployeeCode VARCHAR(50),
    AttendanceDate DATE,
    InTime NVARCHAR(255),
    OutTime NVARCHAR(255),
    Duration FLOAT,
    Status NVARCHAR(50),
    PRIMARY KEY (EmployeeCode, AttendanceDate)
);







PRINT '>>> Step 1: Cleaning conflicting device punches in DeviceLogs and Partition Tables...';
DELETE d
FROM dbo.DeviceLogs d
WHERE d.UserId IN (SELECT DISTINCT UserId FROM #CleanPunches)
  AND d.LogDate >= '2026-07-26 00:00:00' AND d.LogDate <= '2026-08-26 23:59:59'
  AND NOT EXISTS (
      SELECT 1 FROM #CleanPunches cp 
      WHERE cp.UserId = d.UserId AND cp.LogDate = d.LogDate
  );

IF OBJECT_ID('dbo.DeviceLogs_7_2026', 'U') IS NOT NULL
BEGIN
    DELETE d
    FROM dbo.DeviceLogs_7_2026 d
    WHERE d.UserId IN (SELECT DISTINCT UserId FROM #CleanPunches)
      AND d.LogDate >= '2026-07-26 00:00:00' AND d.LogDate <= '2026-07-31 23:59:59'
      AND NOT EXISTS (
          SELECT 1 FROM #CleanPunches cp 
          WHERE cp.UserId = d.UserId AND cp.LogDate = d.LogDate
      );
END

IF OBJECT_ID('dbo.DeviceLogs_8_2026', 'U') IS NOT NULL
BEGIN
    DELETE d
    FROM dbo.DeviceLogs_8_2026 d
    WHERE d.UserId IN (SELECT DISTINCT UserId FROM #CleanPunches)
      AND d.LogDate >= '2026-08-01 00:00:00' AND d.LogDate <= '2026-08-26 23:59:59'
      AND NOT EXISTS (
          SELECT 1 FROM #CleanPunches cp 
          WHERE cp.UserId = d.UserId AND cp.LogDate = d.LogDate
      );
END
PRINT '    ✅ Conflicting punches removed.';

PRINT '>>> Step 2: Inserting valid biometric punches into dbo.DeviceLogs & Partitions...';
SELECT 
    cp.LogDate, 
    1, 
    cp.UserId, 
    cp.LogDate, 
    cp.Direction, 
    cp.Direction
FROM #CleanPunches cp
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.DeviceLogs d WITH (NOLOCK)
    WHERE d.UserId = cp.UserId AND d.LogDate = cp.LogDate
);

IF OBJECT_ID('dbo.DeviceLogs_7_2026', 'U') IS NOT NULL
BEGIN
    SELECT cp.LogDate, 1, cp.UserId, cp.LogDate, cp.Direction, cp.Direction
    FROM #CleanPunches cp
    WHERE MONTH(cp.LogDate) = 7 AND YEAR(cp.LogDate) = 2026
      AND NOT EXISTS (
          SELECT 1 FROM dbo.DeviceLogs_7_2026 d WITH (NOLOCK) 
          WHERE d.UserId = cp.UserId AND d.LogDate = cp.LogDate
      );
END

IF OBJECT_ID('dbo.DeviceLogs_8_2026', 'U') IS NOT NULL
BEGIN
    SELECT cp.LogDate, 1, cp.UserId, cp.LogDate, cp.Direction, cp.Direction
    FROM #CleanPunches cp
    WHERE MONTH(cp.LogDate) = 8 AND YEAR(cp.LogDate) = 2026
      AND NOT EXISTS (
          SELECT 1 FROM dbo.DeviceLogs_8_2026 d WITH (NOLOCK) 
          WHERE d.UserId = cp.UserId AND d.LogDate = cp.LogDate
      );
END
PRINT '    ✅ All valid biometric punches synced into DeviceLogs.';

PRINT '>>> Step 3: Updating dbo.AttendanceLogs with verified Excel records...';
-- 3.1 Update existing records in dbo.AttendanceLogs
UPDATE a
SET 
    a.InTime = ca.InTime,
    a.OutTime = ca.OutTime,
    a.Duration = ca.Duration,
    a.Status = ca.Status,
    a.Remarks = 'Excel Verified'
FROM dbo.AttendanceLogs a
JOIN dbo.Employees e ON a.EmployeeId = e.EmployeeId
JOIN #CleanAttendance ca 
    ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = ca.EmployeeCode 
   AND CAST(a.AttendanceDate AS DATE) = ca.AttendanceDate;

-- 3.2 Insert missing records in dbo.AttendanceLogs
SELECT 
    CAST(ca.AttendanceDate AS DATETIME),
    e.EmployeeId,
    ca.InTime,
    ca.OutTime,
    ca.Duration,
    ca.Status,
    'Excel Verified'
FROM #CleanAttendance ca
JOIN dbo.Employees e ON LTRIM(RTRIM(CAST(e.EmployeeCode AS VARCHAR(50)))) = ca.EmployeeCode
WHERE NOT EXISTS (
    SELECT 1 FROM dbo.AttendanceLogs a 
    WHERE a.EmployeeId = e.EmployeeId AND CAST(a.AttendanceDate AS DATE) = ca.AttendanceDate
);

-- 3.3 Sanitize any remaining empty/NULL strings across the month in dbo.AttendanceLogs
UPDATE dbo.AttendanceLogs
SET InTime = '1900-01-01 00:00:00'
WHERE (InTime IS NULL OR LTRIM(RTRIM(InTime)) = '')
  AND AttendanceDate >= '2026-07-26' AND AttendanceDate <= '2026-08-25';

UPDATE dbo.AttendanceLogs
SET OutTime = '1900-01-01 00:00:00'
WHERE (OutTime IS NULL OR LTRIM(RTRIM(OutTime)) = '')
  AND AttendanceDate >= '2026-07-26' AND AttendanceDate <= '2026-08-25';

-- Drop temp tables
DROP TABLE #CleanPunches;
DROP TABLE #CleanAttendance;

PRINT '    ✅ dbo.AttendanceLogs successfully updated with 100% verified Excel records.';
PRINT '';
PRINT '======================================================================';
PRINT '✅ NATIVE ATTENDANCE & BIOMETRIC SYNC COMPLETED SUCCESSFULLY!';
PRINT '======================================================================';
GO

-- Verification: Check Abdul Khadar Days 18, 19, 20, 21
SELECT 
    e.EmployeeCode,
    e.EmployeeName,
    CONVERT(VARCHAR(10), a.AttendanceDate, 120) AS ShiftDate,
    a.InTime,
    a.OutTime,
    a.Duration AS DurationMins,
    a.Status,
    a.Remarks
FROM dbo.AttendanceLogs a WITH (NOLOCK)
JOIN dbo.Employees e WITH (NOLOCK) ON a.EmployeeId = e.EmployeeId
WHERE e.EmployeeCode = '420001'
  AND a.AttendanceDate >= '2026-08-18' AND a.AttendanceDate <= '2026-08-21'
ORDER BY a.AttendanceDate;
GO
